let db=JSON.parse(localStorage.getItem(KEY)||'null')||structuredClone(seed);
if(!Array.isArray(db.vendorMembers)) db.vendorMembers=[];
if(!Array.isArray(db.partners)) db.partners=[];
// Admin access is restricted to exactly the four authorized accounts.
db.users=AUTH_USERS.map(u=>({...u}));
// Backward-compatible defaults for data created before Excel Payments import.
db.excelSync=db.excelSync||{lastSync:'',fileName:'',rows:0,records:0,history:[]};
db.payments=Array.isArray(db.payments)?db.payments:[];
db.weeklyPayments=Array.isArray(db.weeklyPayments)?db.weeklyPayments:[];
if(!Array.isArray(db.riders)||db.riders.length===0) db.riders=seed.riders.map(r=>({...r}));
if(!Array.isArray(db.hubs)||db.hubs.length===0) db.hubs=seed.hubs.map(h=>({...h,contacts:Array.isArray(h.contacts)?h.contacts:[],notes:[]}));
/* Hub data upgrade/import: preserve existing edits, add every Excel hub once, and merge duplicate contact rows into one hub. */
const seedHubByCode=new Map(seed.hubs.map(h=>[String(h.code||h.name).trim().toLowerCase(),h]));
db.hubs=(Array.isArray(db.hubs)?db.hubs:[]).map(h=>{
  const code=String(h.code||h.name||'').trim().toLowerCase();
  const d=seedHubByCode.get(code);
  return {...(d||{}),...h,code:h.code||d?.code||h.name||'',pincode:h.pincode||d?.pincode||'',location:h.location||d?.location||'',address:h.address||d?.address||'',manager:h.manager||d?.manager||'',phone:h.phone||d?.phone||'',email:h.email||d?.email||'',pod:h.pod||d?.pod||'',region:h.region||d?.region||'',hiName:h.hiName||d?.hiName||'',contacts:Array.isArray(h.contacts)&&h.contacts.length?h.contacts:(d?.contacts||[]),status:h.status||'Active',notes:Array.isArray(h.notes)?h.notes:[]};
});
seed.hubs.forEach(src=>{const key=String(src.code||src.name).trim().toLowerCase();const existing=db.hubs.find(h=>String(h.code||h.name).trim().toLowerCase()===key);if(!existing)db.hubs.push({...src,contacts:(src.contacts||[]).map(c=>({...c})),notes:[]});});

