function strongPassword(p){return /^(?=.*[a-z])(?=.*[A-Z])(?=.*\d)(?=.*[^A-Za-z0-9]).{8,}$/.test(p)}
$$('.password-toggle').forEach(b=>b.onclick=()=>{const i=document.getElementById(b.dataset.target);i.type=i.type==='password'?'text':'password';b.textContent=i.type==='password'?'Show':'Hide'});
$('#loginForm').onsubmit=e=>{e.preventDefault();const id=$('#loginIdentity').value.trim().toLowerCase(),p=$('#loginPassword').value;const u=AUTH_USERS.find(x=>x.email.toLowerCase()===id&&x.password===p);if(!u)return toast('Access denied. Only the 4 authorized administrators can login.');currentUser={...u};localStorage.setItem('owl_session',JSON.stringify(currentUser));localStorage.setItem('owl_auth_verified','1');showApp()};
