function layout(title,sub,actions=''){return `<div class="page-head"><div class="page-title-brand"><img src="logo.jpg" class="page-logo" alt="On The Way Logistics logo"><div><h2>${title}</h2><p>${sub}</p></div></div><div class="actions">${actions}</div></div>`}
