  if(!p){p={id:uid('PAY'),riderId:riderId,rider:rider.name,source:'Weekly View'};db.payments.push(p)}
  Object.assign(p,{riderId:riderId,rider:rider.name,isoDate:isoDate,date:displayDate(isoDate),week:weekStart,lm,primary,club,amount,status,source:p.source==='Weekly View'?'Manual Adjustment':(p.source||'Manual Adjustment'),importKey:p.importKey||((riderId||normText(rider.name))+'|'+isoDate)});
