function yesNoIcon(value){
  const v=String(value??'').trim().toLowerCase();
  if(v==='yes'||v==='y'||v==='true'||v==='1') return '<span class="yes-no-icon yes" title="Yes">✓</span>';
  if(v==='no'||v==='n'||v==='false'||v==='0') return '<span class="yes-no-icon no" title="No">✕</span>';
  return esc(value??'');
}

function normText(v){return String(v??'').trim().toLowerCase().replace(/[^a-z0-9]+/g,' ')}
function excelDate(v){if(v instanceof Date&&!isNaN(v))return v.toISOString().slice(0,10);if(typeof v==='number'&&window.XLSX?.SSF){const d=XLSX.SSF.parse_date_code(v);if(d)return `${d.y}-${String(d.m).padStart(2,'0')}-${String(d.d).padStart(2,'0')}`;}let s=String(v??'').trim();if(!s)return '';let m=s.match(/^(\d{1,2})[\/.-](\d{1,2})[\/.-](\d{2,4})$/);if(m){let y=Number(m[3]);if(y<100)y+=2000;return `${y}-${String(Number(m[2])).padStart(2,'0')}-${String(Number(m[1])).padStart(2,'0')}`;}let d=new Date(s);return isNaN(d)?'':d.toISOString().slice(0,10)}
function displayDate(iso){if(!iso)return '';const [y,m,d]=iso.split('-');return d&&m&&y?`${d}/${m}/${y}`:iso}
function parseOrderPair(v){if(v==null||v==='')return {lm:0,primary:0,club:0};let s=String(v).trim().replace(/,/g,'');let m=s.match(/(\d+(?:\.\d+)?)\s*\/\s*(\d+(?:\.\d+)?)/);if(m){const lm=Number(m[1]),primary=Number(m[2]);return {lm,primary,club:Math.max(0,lm-primary)}}let n=Number(s.replace(/[^0-9.-]/g,''));return {lm:isFinite(n)?n:0,primary:0,club:0}}
function parseRate(v){const s=String(v??'');const nums=[...s.matchAll(/₹?\s*(\d+(?:\.\d+)?)\s*(?:Pri(?:mary)?|P)?/gi)].map(m=>Number(m[1]));const clubMatch=s.match(/₹?\s*(\d+(?:\.\d+)?)\s*Club/i);let primary=nums[0]||0,club=clubMatch?Number(clubMatch[1]):0;if(!club){const all=[...s.matchAll(/₹?\s*(\d+(?:\.\d+)?)/g)].map(m=>Number(m[1]));if(all.length>1)club=all[1]}return {primary,club}}
function riderForExcel(id,name,hub){let r=db.riders.find(x=>id&&String(x.id).trim().toLowerCase()===String(id).trim().toLowerCase());if(!r&&name){const n=normText(name), base=normText(String(name).replace(/\([^)]*\)/g,''));r=db.riders.find(x=>{const xn=normText(x.name), xb=normText(String(x.name).replace(/\([^)]*\)/g,''));return xn===n||xb===base||((base.length>5)&&(xb.startsWith(base)||base.startsWith(xb)));});}if(!r){const newId=id?String(id).trim():`IMP-${String(db.riders.length+1).padStart(4,'0')}`;r={name:String(name||newId).trim(),id:newId,phone:'',location:hub||'',hub:hub||'',status:'Active',weekly:0,notes:'Created automatically from Excel'};db.riders.push(r)}else if(hub&&!r.hub)r.hub=hub;return r}
function upsertDailyPayment(rec){const key=(rec.riderId||normText(rec.rider))+'|'+rec.date;let p=db.payments.find(x=>x.importKey===key||(x.riderId&&rec.riderId&&x.riderId===rec.riderId&&x.date===rec.date));if(!p){p={id:uid('PAY'),importKey:key};db.payments.push(p)}Object.assign(p,rec);return p}
async function importPaymentsExcel(file){
 const ext=(String(file?.name||'').split('.').pop()||'').toLowerCase();
 if(!['xlsx','xls'].includes(ext)){toast('Invalid file format. Please upload an .xlsx or .xls Excel file.');return}
 if(!window.XLSX){toast('Excel reader is not loaded. Check your internet connection and try again.');return}
 try{
  const wb=XLSX.read(await file.arrayBuffer(),{type:'array',cellDates:true});
  const norm=h=>String(h??'').trim().toLowerCase().replace(/[₹()]/g,'').replace(/[^a-z0-9]+/g,' ').trim();
  const aliases={id:['payment id','transaction id','invoice number','invoice no','order id','reference id','transaction reference'],riderId:['rider id','rider_id'],name:['rider name','rider_name','name'],date:['order date','order_date','date'],lm:['total lm orders','total lm order','lm orders','lm'],primary:['total primary orders','total primary order','total primary','primary orders','primary'],club:['total club orders','total club order','total club','club orders','club'],rate:['rate applicable','rate'],amount:['payout amount','payout amount inr','payout']};
  const val=(row,names)=>{const wanted=names.map(norm);const k=Object.keys(row).find(k=>wanted.includes(norm(k)));return k===undefined?'':row[k]};
  const money=v=>{if(v===null||v===undefined||String(v).trim()==='')return null;const n=Number(String(v).replace(/,/g,'').replace(/[₹$]/g,'').replace(/[^\d.-]/g,''));return Number.isFinite(n)&&n>=0?n:null};
  const required=['name','date','lm','primary','club'];
  let inserted=0,updated=0,invalid=0,workAdded=0,weeklyUpdated=0,completedAmount=0,processed=0;
  const dailyName=wb.SheetNames.find(n=>norm(n)==='all riders daily settlement');
  if(dailyName){
   const raw=XLSX.utils.sheet_to_json(wb.Sheets[dailyName],{defval:'',raw:true});
   if(!raw.length)throw new Error('The All Riders Daily Settlement sheet is empty.');
   const headers=Object.keys(raw[0]);
   const missing=required.filter(k=>!headers.some(h=>aliases[k].map(norm).includes(norm(h))));
   if(missing.length)throw new Error('Missing required columns: '+missing.join(', '));
   const batch=[]; const seen=new Set();
   for(let i=0;i<raw.length;i++){
    const row=raw[i], name=String(val(row,aliases.name)).trim(), riderId=String(val(row,aliases.riderId)).trim(), date=excelDate(val(row,aliases.date));
    const lm=money(val(row,aliases.lm)), primary=money(val(row,aliases.primary)), club=money(val(row,aliases.club));
    const rate=parseRate(val(row,aliases.rate)); let amount=money(val(row,aliases.amount));
    if(!name||!date||lm===null||primary===null||club===null||primary+club!==lm){invalid++;continue}
    if(amount===null)amount=Math.round((primary*rate.primary+club*rate.club)*100)/100;
    const rider=riderForExcel(riderId,name,val(row,['Hub','hub']));
    const key=(rider.id||normText(name))+'|'+date;
    if(seen.has(key)){invalid++;continue} seen.add(key);
    batch.push({rider,date,lm,primary,club,amount,rate:val(row,aliases.rate),source:file.name,key});
   }
   for(const rec of batch){
    const old=db.payments.find(p=>p.importKey===rec.key||((p.riderId===rec.rider.id)&&String(p.isoDate||excelDate(p.date))===rec.date));
    const pay={id:old?.id||uid('PAY'),importKey:rec.key,riderId:rec.rider.id,rider:rec.rider.name,date:displayDate(rec.date),isoDate:rec.date,week:isoWeekStart(rec.date),lm:rec.lm,primary:rec.primary,club:rec.club,amount:rec.amount,status:rec.amount>0?'Completed':'Pending',source:file.name,rate:rec.rate,updatedAt:new Date().toISOString()};
    if(old){Object.assign(old,pay);updated++}else{db.payments.push(pay);inserted++}
    const wk=rec.rider.id+'|'+rec.date, ow=db.work.find(w=>w.excelKey===wk);
    const work={id:ow?.id||uid('WRK'),excelKey:wk,date:displayDate(rec.date),rider:rec.rider.name,riderId:rec.rider.id,orders:rec.lm,type:'Excel Daily Settlement',notes:`LM ${rec.lm} / Primary ${rec.primary} / Club ${rec.club}`,lm:rec.lm,primary:rec.primary,club:rec.club,source:file.name,updatedAt:new Date().toISOString()};
    if(ow)Object.assign(ow,work);else{db.work.push(work);workAdded++} processed++;
   }
  } else {
   // Wide-format Weekly Summary: validate NAME plus at least one date column.
   // Find a wide-format payment sheet by its contents, not only by its tab name.
   // Many customer workbooks use Sheet1, Payments, or a custom tab name.
   let wideName=wb.SheetNames.find(n=>norm(n)==='weekly summary')||wb.SheetNames.find(n=>/summary|settlement|payment/i.test(n));
   let matrix=[],hr=-1;
   const looksLikeWideSheet=(sheetName)=>{
    const rows=XLSX.utils.sheet_to_json(wb.Sheets[sheetName],{header:1,defval:'',raw:true});
    for(let i=0;i<Math.min(rows.length,30);i++){
     const cells=rows[i]||[];
     const hasName=cells.some(v=>['name','rider name','rider_name'].includes(norm(v)));
     const hasDates=cells.some(v=>!!excelDate(v));
     if(hasName&&hasDates)return {rows,headerRow:i};
    }
    return null;
   };
   let detected=wideName?looksLikeWideSheet(wideName):null;
   if(!detected){
    for(const sheetName of wb.SheetNames){const candidate=looksLikeWideSheet(sheetName);if(candidate){wideName=sheetName;detected=candidate;break}}
   }
   if(!detected)throw new Error('Could not detect a payment sheet. Add a header row with Rider Name/NAME and dated order columns, or use the All Riders Daily Settlement columns.');
   matrix=detected.rows;hr=detected.headerRow;
   if(hr<0)throw new Error('Required columns missing: NAME and dated order columns.');
   const headers=matrix[hr].map(v=>String(v??'').trim()), ni=headers.findIndex(v=>['name','rider name','rider_name'].includes(norm(v))), dates=headers.map((h,i)=>({i,date:excelDate(h)})).filter(x=>x.date);
   if(!dates.length)throw new Error('No valid date columns found in the Excel sheet.');
   const paymentCol=headers.findIndex(v=>norm(v).includes('payment completed'));
   for(let ri=hr+1;ri<matrix.length;ri++){
    const row=matrix[ri],name=String(row[ni]??'').trim();if(!name||/^(total|s no|s\.no)/i.test(name))continue;
    const rider=riderForExcel('',name,''), weekStart=isoWeekStart(dates.map(x=>x.date).sort()[0]);let lmSum=0,pSum=0,cSum=0,days=0;
    for(const dc of dates){const cell=String(row[dc.i]??'').trim();if(!cell)continue;const pair=parseOrderPair(cell);if(!Number.isFinite(pair.lm)||pair.lm<0||pair.primary<0||pair.club<0||Math.abs(pair.lm-pair.primary-pair.club)>0.001){invalid++;continue}if(pair.lm===0&&pair.primary===0&&pair.club===0)continue;
      const key=rider.id+'|'+dc.date,old=db.payments.find(p=>p.importKey===key||p.riderId===rider.id&&String(p.isoDate||excelDate(p.date))===dc.date),pay={id:old?.id||uid('PAY'),importKey:key,riderId:rider.id,rider:rider.name,date:displayDate(dc.date),isoDate:dc.date,week:weekStart,lm:pair.lm,primary:pair.primary,club:pair.club,amount:Number(old?.amount||0),status:old?.status||'Pending',source:file.name,updatedAt:new Date().toISOString()};if(old){Object.assign(old,pay);updated++}else{db.payments.push(pay);inserted++}const ow=db.work.find(w=>w.excelKey===key),work={id:ow?.id||uid('WRK'),excelKey:key,date:displayDate(dc.date),rider:rider.name,riderId:rider.id,orders:pair.lm,type:'Excel Daily Settlement',notes:`LM ${pair.lm} / Primary ${pair.primary} / Club ${pair.club}`,lm:pair.lm,primary:pair.primary,club:pair.club,source:file.name};if(ow)Object.assign(ow,work);else{db.work.push(work);workAdded++}lmSum+=pair.lm;pSum+=pair.primary;cSum+=pair.club;days++;processed++;
    }
    if(weekStart){const amount=paymentCol>=0?(money(row[paymentCol])??0):0,key=rider.id+'|'+weekStart;let wp=db.weeklyPayments.find(x=>x.key===key);if(!wp){wp={key,riderId:rider.id,rider:rider.name,weekStart};db.weeklyPayments.push(wp)}Object.assign(wp,{amount,status:amount>0?'Completed':'Pending',source:file.name,days,lm:lmSum,primary:pSum,club:cSum,updatedAt:new Date().toISOString()});weeklyUpdated++;completedAmount+=amount}
   }
  }
  if(!processed)throw new Error('No valid payment rows were found. Check required columns and row data.');
  weeklyPaymentSummary().forEach(x=>{const r=db.riders.find(r=>r.id===x.riderId||normText(r.name)===normText(x.rider));if(r)r.weekly=Number(x.displayAmount||0)});
  const now=new Date().toLocaleString('en-IN');db.excelSync={lastSync:now,fileName:file.name,rows:processed,records:processed,history:[...(db.excelSync?.history||[]),{time:now,fileName:file.name,records:processed,inserted,updated,invalid,workAdded,weeklyUpdated,completedAmount}].slice(-20)};
  save();render('payments');toast(`Excel import successful: ${inserted} inserted, ${updated} updated, ${invalid} invalid rows skipped.`);
 }catch(err){console.error(err);toast('Excel import failed: '+(err.message||'Unknown error'))}
}
