function partnerPrefix(type){return String(type||'').toLowerCase()==='vendor'?'VN':'FP'}
function nextPartnerAppId(type, excludeId=''){
  const prefix=partnerPrefix(type); let max=0;
  (Array.isArray(db.partners)?db.partners:[]).forEach(p=>{
    if(p.id===excludeId)return;
    const m=String(p.appId||'').match(new RegExp('^'+prefix+'-(\\d{6})$','i'));
    if(m) max=Math.max(max,Number(m[1]));
  });
  return prefix+'-'+String(max+1).padStart(6,'0');
}
function normalizePartnerIds(){
  if(!Array.isArray(db.partners)) db.partners=[];
  const used=new Set(); const counters={FP:0,VN:0};
  db.partners.forEach(p=>{
    p.type=(String(p.type||'').toLowerCase()==='vendor')?'Vendor':'Franchise';
    const prefix=partnerPrefix(p.type); const id=String(p.appId||'');
    const m=id.match(/^(FP|VN)-(\d{6})$/i);
    if(m && !used.has(id.toUpperCase())){used.add(id.toUpperCase());counters[prefix]=Math.max(counters[prefix],Number(m[2]));return;}
    counters[prefix]++; let candidate=prefix+'-'+String(counters[prefix]).padStart(6,'0');
    while(used.has(candidate)) {counters[prefix]++;candidate=prefix+'-'+String(counters[prefix]).padStart(6,'0')}
    p.appId=candidate; used.add(candidate);
  });
}
normalizePartnerIds();
(db.partners||[]).forEach(p=>{if(p.status==='Approved')p.status='Accepted'});
save();
