function vendorRows(list=(Array.isArray(db.partners)?db.partners:[]).filter(p=>p.type==='Vendor')){const body=$('#vendorRows');if(!body)return;body.innerHTML=list.map(p=>`<tr><td><b>${esc(p.appId)}</b></td><td>${esc(p.name)}</td><td>${esc(p.contact||'')}</td><td>${esc(p.mobile||p.whatsapp||'')}</td><td>${esc(p.street||p.address||'')}${p.locality&&p.locality!==(p.street||p.address)?' · '+esc(p.locality):''}</td><td>${esc(p.nearby||p.landmark||'')}</td><td>${esc([p.city||p.district,p.pincode].filter(Boolean).join(' · '))}</td><td>${statusBadge(p.status,p)}</td><td><div class="row-actions">${decisionButtons(p)}<button class="btn-sm" onclick="viewPartner('${esc(p.id)}')">View form</button><button class="btn-sm" onclick="editPartner('${esc(p.id)}')">✏️ Edit</button></div></td></tr>`).join('')||'<tr><td colspan="9" class="empty">No vendor records found.</td></tr>'}
function franchiseRows(list=(Array.isArray(db.partners)?db.partners:[]).filter(p=>p.type==='Franchise')){const body=$('#franchiseRows');if(!body)return;body.innerHTML=list.map(p=>`<tr><td><b>${esc(p.appId)}</b></td><td>${esc(p.name)}</td><td>${esc(p.contact||'')}</td><td>${esc(p.mobile||p.whatsapp||'')}</td><td>${esc(p.street||p.address||'')}${p.locality&&p.locality!==(p.street||p.address)?' · '+esc(p.locality):''}</td><td>${esc(p.nearby||p.landmark||'')}</td><td>${esc([p.city||p.district,p.pincode].filter(Boolean).join(' · '))}</td><td>${statusBadge(p.status,p)}</td><td><div class="row-actions">${decisionButtons(p)}<button class="btn-sm" onclick="viewPartner('${esc(p.id)}')">View form</button><button class="btn-sm" onclick="editPartner('${esc(p.id)}')">✏️ Edit</button></div></td></tr>`).join('')||'<tr><td colspan="9" class="empty">No franchise records found.</td></tr>'}
function vendorMemberRows(){const body=$('#vendorMemberRows');if(!body)return;const isAdmin=currentUser?.role==='admin';const visible=(db.vendorMembers||[]).filter(m=>isAdmin||normText(m.ownerEmail)===normText(currentUser?.email));body.innerHTML=visible.map(m=>`<tr><td><b>${esc(m.memberId)}</b></td><td>${esc(m.name)}</td><td>${esc(m.clientType||'Vendor')}</td><td>${esc(m.vendorName||m.franchiseName||'')}</td><td>${esc(m.ownerEmail||'')}</td><td>${esc(m.phone||'')}</td><td>${esc(m.role||'Member')}</td><td>${esc(m.street||m.area||'')}</td><td><span class="badge success">Active</span></td></tr>`).join('')||'<tr><td colspan="9" class="empty">No client members found.</td></tr>'}
function vendorMemberModal(m=null){const clients=(db.partners||[]).filter(p=>p.type==='Vendor'||p.type==='Franchise');const currentType=m?.clientType||'Vendor';openModal(`<h3>${m?'Edit':'Add'} Client Member</h3><form id="vendorMemberForm" class="form-grid"><div class="field"><label>Member ID</label><input id="vmId" value="${esc(m?.memberId||('CM-'+String((db.vendorMembers||[]).length+1).padStart(6,'0')))}" readonly></div><div class="field"><label>Client Type</label><select id="vmType"><option ${currentType==='Vendor'?'selected':''}>Vendor</option><option ${currentType==='Franchise'?'selected':''}>Franchise</option></select></div><div class="field"><label>Vendor / Franchise</label><select id="vmVendor"></select></div><div class="field"><label>Member Name</label><input id="vmName" required value="${esc(m?.name||'')}"></div><div class="field"><label>Owner Email</label><input id="vmOwner" type="email" required value="${esc(m?.ownerEmail||'')}" placeholder="Client owner's email"></div><div class="field"><label>Phone</label><input id="vmPhone" value="${esc(m?.phone||'')}"></div><div class="field"><label>Role</label><input id="vmRole" value="${esc(m?.role||'Member')}"></div><div class="field"><label>Street / Area</label><input id="vmStreet" value="${esc(m?.street||'')}"></div><div class="field"><label>Nearby Location / Landmark</label><input id="vmNear" value="${esc(m?.nearby||'')}"></div><div class="field"><label>City</label><input id="vmCity" value="${esc(m?.city||'')}"></div><div class="field"><label>Pincode</label><input id="vmPin" value="${esc(m?.pincode||'')}"></div><div class="field"><label>Status</label><select id="vmStatus"><option ${m?.status!=='Inactive'?'selected':''}>Active</option><option ${m?.status==='Inactive'?'selected':''}>Inactive</option></select></div><div class="field span2"><label>Private Notes</label><textarea id="vmNotes">${esc(m?.notes||'')}</textarea></div><div class="modal-actions span2"><button type="button" class="ghost" onclick="closeModal()">Cancel</button><button class="primary">${m?'Update Member':'Save Member'}</button></div></form>`);
 const fill=()=>{const type=$('#vmType').value;const list=clients.filter(x=>x.type===type);$('#vmVendor').innerHTML=list.map(v=>`<option value="${esc(v.id)}" ${m?.vendorId===v.id?'selected':''}>${esc(v.appId+' - '+v.name)}</option>`).join('')||'<option value="">No clients available</option>'};$('#vmType').onchange=fill;fill();
 $('#vendorMemberForm').onsubmit=e=>{e.preventDefault();const v=db.partners.find(x=>x.id===$('#vmVendor').value);const type=$('#vmType').value;const x={id:m?.id||uid('CM'),memberId:$('#vmId').value,name:$('#vmName').value.trim(),clientType:type,vendorId:v?.id||'',vendorName:type==='Vendor'?(v?.name||''):'',franchiseName:type==='Franchise'?(v?.name||''):'',ownerEmail:$('#vmOwner').value.trim(),phone:$('#vmPhone').value.trim(),role:$('#vmRole').value.trim()||'Member',street:$('#vmStreet').value.trim(),nearby:$('#vmNear').value.trim(),city:$('#vmCity').value.trim(),pincode:$('#vmPin').value.trim(),status:$('#vmStatus').value,notes:$('#vmNotes').value};if(m)Object.assign(m,x);else db.vendorMembers.push(x);save();closeModal();render('client');toast(m?'Client member updated':'Client member added')}
}
window.editVendorMember=id=>{const m=(db.vendorMembers||[]).find(x=>x.id===id);if(m)vendorMemberModal(m)};
function bindClient(){
 const nv=$('#newVendor'), nf=$('#newFranchise'), mb=$('#newClientMember');
 if(nv)nv.onclick=()=>partnerModal({type:'Vendor'}); if(nf)nf.onclick=()=>partnerModal({type:'Franchise'});
 if(mb)mb.onclick=()=>{if(!(db.partners||[]).some(p=>p.type==='Vendor'||p.type==='Franchise'))return toast('Add a vendor or franchise first');vendorMemberModal()};
 const q=$('#clientSearch'),sf=$('#clientStatusFilter'); const apply=()=>{const term=(q?.value||'').trim().toLowerCase();const all=(db.partners||[]).filter(statusFilterFn(sf?.value));const matches=list=>!term?list:list.filter(p=>[p.appId,p.type,p.name,p.contact,p.mobile,p.whatsapp,p.email,p.state,p.district,p.city,p.pincode,p.status,p.address,p.street,p.locality,p.nearby,p.landmark,p.remarks].join(' ').toLowerCase().includes(term));vendorRows(matches(all.filter(p=>p.type==='Vendor')));franchiseRows(matches(all.filter(p=>p.type==='Franchise')))};if(q)q.oninput=apply;if(sf)sf.onchange=apply;window.__clientApply=apply;apply();vendorMemberRows();syncPartnerApplications();
 $$('.tab-btn').forEach(b=>b.onclick=()=>{$$('.tab-btn').forEach(x=>x.classList.remove('active'));b.classList.add('active');const t=b.dataset.clientTab;$('#clientVendorPanel')?.classList.toggle('hidden',t!=='vendor');$('#clientFranchisePanel')?.classList.toggle('hidden',t!=='franchise')});
}
function partners(){return layout('Partner Applications','Manage Franchise and Vendor applications.','<button class="primary" id="newPartner">+ New Application</button>')+`<div class="cards">${stat('Total',db.partners.length,'partnerStatTotal')}${stat('Franchise',db.partners.filter(p=>p.type==='Franchise').length,'partnerStatFranchise')}${stat('Vendor',db.partners.filter(p=>p.type==='Vendor').length,'partnerStatVendor')}${stat('Pending',db.partners.filter(isPendingPartner).length,'partnerStatPending')}${stat('Accepted',db.partners.filter(p=>p.status==='Accepted').length,'partnerStatAccepted')}${stat('Rejected',db.partners.filter(p=>p.status==='Rejected').length,'partnerStatRejected')}</div><div class="card"><div class="hub-list-toolbar"><div><h3>Applications</h3><span class="muted">FP = Franchise &nbsp;|&nbsp; VN = Vendor</span></div><div class="partner-filters">${statusFilterSelect('partnerStatusFilter')}<input class="hub-search" id="partnerSearch" placeholder="Search Application ID, name, type, phone, city..." autocomplete="off"></div></div><div class="table-wrap"><table class="table"><thead><tr><th>Application ID</th><th>Type</th><th>Name</th><th>Contact</th><th>Phone</th><th>Location</th><th>Status</th><th>Actions</th></tr></thead><tbody id="partnerRows"></tbody></table></div></div>`}
function partnerRows(list=db.partners){const body=$('#partnerRows');if(!body)return;body.innerHTML=list.map(p=>`<tr><td><b>${esc(p.appId)}</b></td><td>${esc(p.type)}</td><td>${esc(p.name)}</td><td>${esc(p.contact||'')}</td><td>${esc(p.mobile||p.whatsapp||'')}</td><td>${esc(p.district||'')}${p.district&&p.city?', ':''}${esc(p.city||'')}</td><td>${statusBadge(p.status,p)}</td><td><div class="row-actions">${decisionButtons(p)}<button class="btn-sm" onclick="viewPartner('${esc(p.id)}')">View form</button><button class="btn-sm partner-edit-btn" title="Edit application" onclick="editPartner('${esc(p.id)}')">✏️ Edit</button></div></td></tr>`).join('')||'<tr><td colspan="8" class="empty">No applications found.</td></tr>'}
const PARTNER_API_BASE=window.OTW_API_BASE||((location.protocol==='file:'||['5500','5501'].includes(location.port))?'http://localhost:8080':location.origin);
{const v=document.getElementById('vendorPortalLink');if(v&&(location.protocol==='file:'||['5500','5501'].includes(location.port)||window.OTW_API_BASE))v.href=PARTNER_API_BASE+'/vendor/';}
let partnerSyncBusy=false,partnerSyncFailed=false,knownPartnerIds=null,partnerPollTimer=null;
const PARTNER_POLL_MS=30000;
function mapServerPartner(a){return {
  ...a, id:a.id,appId:a.appId,type:a.type==='Vendor'?'Vendor':'Franchise',
  name:a.name||a.fullName||'',contact:a.contact||a.fullName||'',
  mobile:a.mobile||a.contactNumber||'',whatsapp:a.whatsapp||a.whatsappNumber||'',
  email:a.email||a.gmail||'',state:a.state||'Andhra Pradesh',district:a.district||'',
  city:a.city||a.cityOrVillage||'',pincode:a.pincode||'',street:a.street||a.locality||'',
  locality:a.locality||a.street||'',nearby:a.nearby||a.landmark||'',landmark:a.landmark||a.nearby||'',
  education:a.education||a.educationalQualification||'',status:a.status==='Approved'?'Accepted':(a.status||'New'),
  address:a.address||a.fullAddress||'',remarks:a.remarks||'',submittedAt:a.submittedAt||'',serverSynced:true
}}
function partnerApi(path='',options={}){return fetch(PARTNER_API_BASE+'/api/partner-applications'+path,{...options,headers:{'Content-Type':'application/json','X-Admin-Email':currentUser?.email||'',...(options.headers||{})}})}
const PARTNER_DECIDED=['Accepted','Rejected'];
function isPendingPartner(p){return !PARTNER_DECIDED.includes(p.status)}
function statusFilterSelect(id){return `<select id="${id}" class="status-filter" aria-label="Filter by status"><option value="">All statuses</option><option value="pending">Pending</option><option value="Accepted">Accepted</option><option value="Rejected">Rejected</option></select>`}
function statusFilterFn(v){return !v?()=>true:v==='pending'?isPendingPartner:p=>p.status===v}
function decisionButtons(p){if(!isPendingPartner(p))return '';const id=esc(p.id);return `<button class="btn-sm accept" onclick="decidePartner('${id}','Accepted')">✓ Accept</button><button class="btn-sm danger" onclick="decidePartner('${id}','Rejected')">✕ Reject</button>`}
function fmtDate(v){const d=new Date(v);return isNaN(d)?String(v||''):d.toLocaleString()}
// Ask to confirm, with an optional note (e.g. reason for rejection), then save on the server.
window.decidePartner=(id,decision)=>{
  const p=(db.partners||[]).find(x=>x.id===id);if(!p)return;
  const accept=decision==='Accepted',undo=decision==='Pending';
  const title=undo?'Undo decision':accept?'Accept application':'Reject application';
  const text=undo?`Move <b>${esc(p.appId)}</b> (${esc(p.name)}) back to <b>Under Review</b>? The current decision (${esc(p.status)}) will be cleared.`
    :`${accept?'Accept':'Reject'} the ${esc(p.type)} application <b>${esc(p.appId)}</b> from <b>${esc(p.name)}</b>?`;
  openModal(`<h3>${title}</h3><p>${text}</p>${undo?'':`<div class="field"><label>${accept?'Note (optional)':'Reason for rejection (optional)'}</label><textarea id="decisionNote" rows="3" placeholder="${accept?'e.g. Documents verified, onboarding call on Monday':'e.g. Area already covered by another franchise'}"></textarea></div>`}<div class="modal-actions"><button type="button" class="ghost" onclick="closeModal()">Cancel</button><button type="button" id="confirmDecision" class="primary ${accept?'accept-fill':undo?'':'danger-fill'}">${undo?'Undo decision':accept?'✓ Accept':'✕ Reject'}</button></div>`);
  $('#decisionNote')?.focus();
  $('#confirmDecision').onclick=async()=>{
    const btn=$('#confirmDecision'),note=($('#decisionNote')?.value||'').trim();
    btn.disabled=true;btn.textContent='Saving…';
    try{
      if(p.serverSynced){
        const r=await partnerApi('/'+encodeURIComponent(p.id)+'/decision',{method:'POST',body:JSON.stringify({decision,note})});
        const out=await r.json().catch(()=>({}));
        if(!r.ok)throw new Error(out.error||('Server responded '+r.status));
        const app=out.application||{};
        Object.assign(p,mapServerPartner(app));
        ['decidedBy','decidedAt','decisionNote'].forEach(k=>{if(!app[k])delete p[k]});
      }else{
        // Record that only exists in this browser.
        if(undo){p.status='Under Review';delete p.decidedBy;delete p.decidedAt;delete p.decisionNote}
        else Object.assign(p,{status:decision,decidedBy:currentUser.email,decidedAt:new Date().toISOString(),decisionNote:note});
      }
      save();closeModal();refreshPartnerViews();
      toast(undo?`${p.appId} moved back to Under Review`:`${p.appId} ${accept?'accepted':'rejected'}`);
    }catch(err){
      console.warn('Could not save decision:',err);btn.disabled=false;btn.textContent=undo?'Undo decision':accept?'✓ Accept':'✕ Reject';
      toast('Could not save - the server is not reachable. Start the backend and try again.');
    }
  };
};
function statusBadge(status,p=null){const s=status||'New';const cls=s==='Accepted'||s==='Approved'?'success':s==='Rejected'?'danger':s==='New'?'info':'warning';const tip=p&&p.decidedBy?` title="${esc(s)} by ${esc(p.decidedBy)} on ${esc(fmtDate(p.decidedAt))}${p.decisionNote?' - '+esc(p.decisionNote):''}"`:'';return `<span class="badge ${cls}"${tip}>${esc(s)}</span>`}
function setText(sel,v){const el=$(sel);if(el)el.textContent=v}
// Refresh counts, tables and the sidebar badge without re-rendering the page (keeps tabs and search).
function refreshPartnerViews(){
  const all=Array.isArray(db.partners)?db.partners:[];
  const fr=all.filter(p=>p.type==='Franchise').length,vn=all.filter(p=>p.type==='Vendor').length,fresh=all.filter(isPendingPartner).length;
  setText('#clientStatTotal',fr+vn);setText('#clientStatVendors',vn);setText('#clientStatFranchises',fr);
  setText('#partnerStatTotal',all.length);setText('#partnerStatFranchise',fr);setText('#partnerStatVendor',vn);setText('#partnerStatPending',all.filter(isPendingPartner).length);setText('#partnerStatAccepted',all.filter(p=>p.status==='Accepted').length);setText('#partnerStatRejected',all.filter(p=>p.status==='Rejected').length);
  if($('#partnerRows')&&window.__partnerApply)window.__partnerApply();
  if(($('#franchiseRows')||$('#vendorRows'))&&window.__clientApply)window.__clientApply();
  if($('#dashNewApps'))setText('#dashNewApps',fresh);
  updatePartnerNavCount();
}
function updatePartnerNavCount(){
  const fresh=(Array.isArray(db.partners)?db.partners:[]).filter(isPendingPartner).length;
  ['partners','client'].forEach(page=>{const btn=document.querySelector(`.nav[data-page="${page}"]`);if(!btn)return;let b=btn.querySelector('.nav-count');if(!fresh){b?.remove();return}if(!b){b=document.createElement('span');b.className='nav-count';btn.appendChild(b)}b.textContent=fresh;b.title=fresh+' application'+(fresh===1?'':'s')+' waiting for Accept / Reject'});
}
async function syncPartnerApplications(){
  if(!currentUser?.email||partnerSyncBusy)return;
  partnerSyncBusy=true;
  try{
    const response=await partnerApi();
    if(!response.ok)throw new Error('Dashboard API responded '+response.status);
    const mapped=(await response.json()).map(mapServerPartner);
    // Tell the admin about applications that arrived since the last check.
    const ids=new Set(mapped.map(p=>p.id));
    if(knownPartnerIds){const arrived=mapped.filter(p=>!knownPartnerIds.has(p.id));if(arrived.length===1)toast(`New ${arrived[0].type} application ${arrived[0].appId} from ${arrived[0].name}`);else if(arrived.length>1)toast(`${arrived.length} new applications received`)}
    knownPartnerIds=ids;
    // Keep records that only exist in this browser (created before the server was used).
    const localOnly=(db.partners||[]).filter(p=>!p.serverSynced&&!ids.has(p.id));
    db.partners=[...mapped,...localOnly];
    save();
    partnerSyncFailed=false;
    refreshPartnerViews();
  }catch(err){
    console.warn('Could not sync partner applications from backend:',err);
    // Warn once (not on every background check) while the admin is looking at applications.
    if(!partnerSyncFailed&&['client','partners'].includes(currentPage))toast('Could not reach the server - start the backend to load website applications');
    partnerSyncFailed=true;
  }finally{partnerSyncBusy=false}
}
function startPartnerPolling(){stopPartnerPolling();knownPartnerIds=null;syncPartnerApplications();partnerPollTimer=setInterval(syncPartnerApplications,PARTNER_POLL_MS)}
function stopPartnerPolling(){if(partnerPollTimer)clearInterval(partnerPollTimer);partnerPollTimer=null}
document.addEventListener('visibilitychange',()=>{if(!document.hidden&&currentUser)syncPartnerApplications()});
function bindPartners(){const b=$('#newPartner');if(b)b.onclick=()=>partnerModal();const q=$('#partnerSearch'),sf=$('#partnerStatusFilter');const apply=()=>{const term=(q?.value||'').trim().toLowerCase();const base=db.partners.filter(statusFilterFn(sf?.value));partnerRows(!term?base:base.filter(p=>[p.appId,p.type,p.name,p.contact,p.mobile,p.whatsapp,p.email,p.state,p.district,p.city,p.pincode,p.status,p.address,p.street,p.locality,p.nearby,p.landmark,p.remarks].join(' ').toLowerCase().includes(term)))};if(q)q.oninput=apply;if(sf)sf.onchange=apply;window.__partnerApply=apply;apply();syncPartnerApplications()}
function partnerModal(p=null){const originalType=p?.type||'Franchise';const editing=!!p?.id;if(!editing)p=null;const appId=p?.appId||(editing?'':nextPartnerAppId(originalType))||'';openModal(`<h3>${editing?'Edit':'New'} Partner Application</h3><form id="partnerForm" class="form-grid"><div class="field"><label>Application ID</label><input id="paAppId" value="${esc(editing?appId:'Assigned when saved')}" readonly></div><div class="field"><label>Partner Type</label><select id="paType"><option ${originalType==='Franchise'?'selected':''}>Franchise</option><option ${originalType==='Vendor'?'selected':''}>Vendor</option></select></div><div class="field"><label>Name / Company</label><input id="paName" required value="${esc(p?.name||'')}"></div><div class="field"><label>Contact Name</label><input id="paContact" value="${esc(p?.contact||'')}"></div><div class="field"><label>Mobile</label><input id="paMobile" value="${esc(p?.mobile||'')}"></div><div class="field"><label>WhatsApp</label><input id="paWhatsapp" value="${esc(p?.whatsapp||'')}"></div><div class="field"><label>Email</label><input id="paEmail" type="email" value="${esc(p?.email||'')}"></div><div class="field"><label>State</label><input id="paState" value="${esc(p?.state||'Andhra Pradesh')}"></div><div class="field"><label>District</label><input id="paDistrict" value="${esc(p?.district||'')}"></div><div class="field"><label>City / Town</label><input id="paCity" value="${esc(p?.city||'')}"></div><div class="field"><label>Street / Locality</label><input id="paStreet" value="${esc(p?.street||p?.locality||'')}"></div><div class="field"><label>Near Location / Landmark</label><input id="paNearby" value="${esc(p?.nearby||p?.landmark||'')}"></div><div class="field"><label>Pincode</label><input id="paPin" value="${esc(p?.pincode||'')}"></div><div class="field"><label>Educational Qualification</label><input id="paEdu" value="${esc(p?.education||'')}"></div><div class="field"><label>Status</label><select id="paStatus">${['New','Contacted','Under Review','Documents Pending','Accepted','Rejected'].map(x=>`<option ${p?.status===x?'selected':''}>${x}</option>`).join('')}</select></div><div class="field span2"><label>Address</label><textarea id="paAddress">${esc(p?.address||'')}</textarea></div><div class="field span2"><label>Services / Remarks</label><textarea id="paRemarks">${esc(p?.remarks||'')}</textarea></div><div class="modal-actions span2"><button type="button" class="ghost" onclick="closeModal()">Cancel</button><button class="primary">${editing?'Update Application':'Save Application'}</button></div></form>`);const typeEl=$('#paType'),idEl=$('#paAppId');typeEl.onchange=()=>{const newType=typeEl.value;if(editing && newType===originalType){idEl.value=p.appId}else{idEl.value=editing&&p.serverSynced?'New ID assigned when saved':editing?nextPartnerAppId(newType,p.id):'Assigned when saved'}};$('#partnerForm').onsubmit=async e=>{e.preventDefault();const type=typeEl.value;
  const x={type,name:$('#paName').value.trim(),contact:$('#paContact').value.trim(),mobile:$('#paMobile').value.trim(),whatsapp:$('#paWhatsapp').value.trim(),email:$('#paEmail').value.trim(),state:$('#paState').value.trim(),district:$('#paDistrict').value.trim(),city:$('#paCity').value.trim(),pincode:$('#paPin').value.trim(),street:$('#paStreet').value.trim(),locality:$('#paStreet').value.trim(),nearby:$('#paNearby').value.trim(),landmark:$('#paNearby').value.trim(),education:$('#paEdu').value.trim(),status:$('#paStatus').value,address:$('#paAddress').value,remarks:$('#paRemarks').value};
  const backTo=['client','partners'].includes(currentPage)?currentPage:'partners';
  const saveBtn=e.target.querySelector('button.primary');
  if(editing&&!p.serverSynced){
    // Record that only exists in this browser: keep the old local behaviour.
    let newAppId=idEl.value;if(type!==originalType)newAppId=nextPartnerAppId(type,p.id);
    Object.assign(p,x,{appId:newAppId});normalizePartnerIds();save();closeModal();render(backTo);toast('Application updated successfully');return;
  }
  // Save on the server so every admin sees the same record.
  if(saveBtn){saveBtn.disabled=true;saveBtn.textContent='Saving…'}
  try{
    const r=editing?await partnerApi('/'+encodeURIComponent(p.id),{method:'PATCH',body:JSON.stringify(x)}):await partnerApi('',{method:'POST',body:JSON.stringify({...x,fullName:x.name,contactName:x.contact})});
    const out=await r.json().catch(()=>({}));
    if(!r.ok)throw new Error(out.error||('Server responded '+r.status));
    const saved=mapServerPartner(out.application||{});
    if(editing){Object.assign(p,saved)}else{db.partners.unshift(saved);knownPartnerIds?.add(saved.id)}
    save();closeModal();render(backTo);toast(editing?`Application ${saved.appId} updated`:`Application ${saved.appId} saved`);
  }catch(err){
    console.warn('Could not save application to server:',err);
    if(saveBtn){saveBtn.disabled=false;saveBtn.textContent=editing?'Update Application':'Save Application'}
    toast('Could not save - the server is not reachable. Start the backend and try again.');
  }
}}window.editPartner=id=>{const p=db.partners.find(x=>x.id===id);if(p)partnerModal(p)};

