/* ========================= Payment Management ========================= */
function ensurePaymentState(){
  if(!Array.isArray(db.autoPays))db.autoPays=[];
  if(!Array.isArray(db.paymentTransactions))db.paymentTransactions=[];
  if(!Array.isArray(db.paymentAudit))db.paymentAudit=[];
  db.paymentConfig=db.paymentConfig||{gateway:'Razorpay',mode:'sandbox',enabled:false,retryCount:2,retryDelayHours:24,reminders:true};
}
ensurePaymentState();
function auditPayment(action,details={}){ensurePaymentState();db.paymentAudit.unshift({id:uid('AUD'),at:new Date().toISOString(),admin:currentUser?.email||'system',action,details});db.paymentAudit=db.paymentAudit.slice(0,500);save()}
function autoPayStatusBadge(s){const cls=s==='Active'?'success':s==='Paused'?'warning':s==='Cancelled'?'danger':'info';return `<span class="badge ${cls}">${esc(s)}</span>`}
function nextAutoDate(date,frequency){const d=new Date((date||new Date().toISOString().slice(0,10))+'T00:00:00');if(frequency==='Daily')d.setDate(d.getDate()+1);else if(frequency==='Weekly')d.setDate(d.getDate()+7);else d.setMonth(d.getMonth()+1);return d.toISOString().slice(0,10)}
function autopaySummary(){ensurePaymentState();const tx=db.paymentTransactions;return {total:tx.length,successful:tx.filter(x=>x.status==='Successful').length,pending:tx.filter(x=>x.status==='Pending').length,failed:tx.filter(x=>x.status==='Failed').length,collected:tx.filter(x=>x.status==='Successful').reduce((a,x)=>a+Number(x.amount||0),0),upcoming:db.autoPays.filter(x=>x.status==='Active').length}}
function paymentGatewayNotice(){return ``}
function payments(){
 ensurePaymentState();
 if(currentUser.role!=='admin')return layout('Payments','Payment details are restricted to admin access.')+`<div class="card"><div class="empty">Only administrators can view payment details.</div></div>`;
 const sync=db.excelSync||{}, weekly=weeklyPaymentSummary();
 const aps=db.autoPays.slice().sort((a,b)=>String(a.nextDate).localeCompare(String(b.nextDate)));
 return layout('Payment Management','Excel rider payments and one-time payment records.',`<label class="primary file-picker payment-import-btn"><input type="file" id="paymentExcelImport" accept=".xlsx,.xls" hidden>📥 Import Excel</label><button class="ghost" id="addPayment">+ Manual Adjustment</button>`)+
 
 

 `<div class="card"><div class="section-head"><div><h3>Weekly Payments — Excel Automatic</h3><p class="muted">LM / Primary / Club update from the imported Excel sheet.</p></div><input class="search" id="paymentWeeklySearch" type="search" placeholder="Search rider name, rider ID or week..." aria-label="Search weekly payments" style="max-width:340px;width:100%"></div><div class="table-wrap"><table class="table"><thead><tr><th>Week</th><th>Rider</th><th>Days</th><th>LM</th><th>Primary</th><th>Club</th><th>Weekly Amount</th></tr></thead><tbody id="paymentWeeklyRows">${weekly.map(p=>`<tr data-payment-search="${esc([weekLabel(p.weekStart),p.rider,p.riderId||''].join(' ')).toLowerCase()}"><td>${esc(weekLabel(p.weekStart))}</td><td><button class="link-btn" onclick="openRiderWeekDetails('${esc(p.riderId||'')}', '${esc(p.weekStart||'')}')">${esc(p.rider)}</button></td><td>${p.days}</td><td>${p.lm}</td><td>${p.primary}</td><td>${p.club}</td><td><b>₹${Number(p.displayAmount||0).toFixed(2)}</b></td></tr>`).join('')||'<tr><td colspan="7" class="empty">No weekly payment records yet. Import your Excel file.</td></tr>'}</tbody></table></div><p id="paymentSearchEmpty" class="empty" style="display:none">No matching payment records.</p></div>`+
 `<div class="card"><div class="section-head"><div><h3>Excel Daily Sync</h3><p class="muted">${sync.fileName?`Last file: <b>${esc(sync.fileName)}</b> · ${sync.records||0} daily records updated`:'No Excel payment sync yet.'}</p></div><div class="sync-meta"><span>Accepted: .xlsx / .xls</span><span>Rider + Date duplicate check</span><span>LM / Primary / Club automatic</span></div></div></div>`

}
function autopayRows(list){return list.map(a=>`<tr><td><b>${esc(a.payerName)}</b><br><small>${esc(a.payerType||'Partner')} · ${esc(a.email||'')}</small></td><td>₹${Number(a.amount||0).toFixed(2)}</td><td>${esc(a.frequency)}</td><td>${esc(a.nextDate||'—')}</td><td>${esc(a.method||'UPI AutoPay')}</td><td>${autoPayStatusBadge(a.status)}</td><td>${esc(a.gateway||'Razorpay')}</td><td><div class="mini-actions">${a.status==='Active'?`<button class="btn-sm" onclick="pauseAutoPay('${a.id}')">Pause</button>`:''}${a.status==='Paused'?`<button class="btn-sm" onclick="resumeAutoPay('${a.id}')">Resume</button>`:''}${a.status!=='Cancelled'?`<button class="btn-sm danger" onclick="cancelAutoPay('${a.id}')">Cancel</button>`:''}</div></td></tr>`).join('')||'<tr><td colspan="8" class="empty">No AutoPay mandates yet.</td></tr>'}
function bindPayments(){
 ensurePaymentState();
 const paymentSearch=$('#paymentWeeklySearch');
 paymentSearch?.addEventListener('input',()=>{const q=paymentSearch.value.trim().toLowerCase();let visible=0;$('#paymentWeeklyRows')?.querySelectorAll('tr[data-payment-search]').forEach(row=>{const match=row.dataset.paymentSearch.includes(q);row.style.display=match?'':'none';if(match)visible++;});const empty=$('#paymentSearchEmpty');if(empty)empty.style.display=(q&&visible===0)?'block':'none';});
 $('#addPayment')?.addEventListener('click',()=>{if(!db.riders.length)return toast('Add a rider first');openModal(`<h3>Manual Payment Adjustment</h3><form id="payForm" class="form-grid"><div class="field"><label>Rider</label><select id="pRider">${db.riders.map(r=>`<option>${esc(r.name)}</option>`).join('')}</select></div><div class="field"><label>Week</label><input id="pWeek" type="week" required></div><div class="field"><label>Amount</label><input id="pAmount" type="number" required min="0"></div><div class="field"><label>Status</label><select id="pStatus"><option>Pending</option><option>Paid</option></select></div><div class="modal-actions span2"><button type="button" class="ghost" onclick="closeModal()">Cancel</button><button class="primary">Save</button></div></form>`);$('#payForm').onsubmit=e=>{e.preventDefault();const rider=db.riders.find(r=>r.name===$('#pRider').value),week=$('#pWeek').value,iso=week?week+'-1':new Date().toISOString().slice(0,10);db.payments.push({id:uid('PAY'),date:displayDate(iso),isoDate:iso,rider:$('#pRider').value,riderId:rider?.id||'',week:isoWeekStart(iso),amount:Number($('#pAmount').value),status:$('#pStatus').value,lm:0,primary:0,club:0,source:'Manual Adjustment'});auditPayment('manual_payment_adjustment',{rider:rider?.id||'',amount:Number($('#pAmount').value),status:$('#pStatus').value});closeModal();render('payments');}});
 $('#paymentExcelImport')?.addEventListener('change',async e=>{const file=e.target.files?.[0];if(file)await importPaymentsExcel(file);e.target.value=''});
 
}
function openAutoPayModal(existing=null){
 const a=existing||{};
 openModal(`<h3>${existing?'Edit':'Create'} AutoPay Authorization</h3><form id="autoPayForm" class="form-grid"><div class="field"><label>Payer / Partner Name</label><input id="apName" required value="${esc(a.payerName||'')}"></div><div class="field"><label>Payer Type</label><select id="apType"><option ${a.payerType==='Vendor'?'selected':''}>Vendor</option><option ${a.payerType==='Franchise'?'selected':''}>Franchise</option><option ${a.payerType==='Rider'?'selected':''}>Rider</option><option ${!a.payerType||a.payerType==='Customer'?'selected':''}>Customer</option></select></div><div class="field"><label>Email</label><input id="apEmail" type="email" value="${esc(a.email||'')}"></div><div class="field"><label>Amount (₹)</label><input id="apAmount" type="number" min="1" step="0.01" required value="${esc(a.amount||'')}"></div><div class="field"><label>Frequency</label><select id="apFrequency"><option ${a.frequency==='Daily'?'selected':''}>Daily</option><option ${a.frequency==='Weekly'||!a.frequency?'selected':''}>Weekly</option><option ${a.frequency==='Monthly'?'selected':''}>Monthly</option></select></div><div class="field"><label>First Payment Date</label><input id="apDate" type="date" required value="${esc(a.nextDate||new Date().toISOString().slice(0,10))}"></div><div class="field"><label>Payment Method</label><select id="apMethod"><option>UPI AutoPay</option><option>Card Recurring</option></select></div><div class="field"><label>Mandate / Gateway ID (after authorization)</label><input id="apMandate" value="${esc(a.mandateId||'')}" placeholder="Filled by gateway backend"></div><div class="field span2"><label class="consent-check"><input id="apConsent" type="checkbox" ${a.consent?'checked':''}> I confirm that the payer has explicitly authorized recurring payments and has been shown the amount, frequency, next payment date and cancellation terms.</label><p class="hint">This form only records the authorization request. It does not charge the payer. A real mandate must be created and confirmed by Razorpay on the server.</p></div><div class="modal-actions span2"><button type="button" class="ghost" onclick="closeModal()">Cancel</button><button type="button" class="secondary" id="authorizeRazorpay">Authorize with Razorpay</button><button class="primary">Save Authorization Request</button></div></form>`);
 const saveAutoPayRecord=()=>{if(!$('#apConsent').checked){toast('Explicit AutoPay consent is required.');return null}ensurePaymentState();const obj={id:a.id||uid('AP'),payerName:$('#apName').value.trim(),payerType:$('#apType').value,email:$('#apEmail').value.trim(),amount:Number($('#apAmount').value),frequency:$('#apFrequency').value,nextDate:$('#apDate').value,method:$('#apMethod').value,mandateId:$('#apMandate').value.trim(),status:a.status||'Pending Authorization',consent:true,consentAt:a.consentAt||new Date().toISOString(),gateway:'Razorpay',createdAt:a.createdAt||new Date().toISOString(),retryCount:0};if(a.id)Object.assign(a,obj);else db.autoPays.push(obj);auditPayment(a.id?'autopay_authorization_updated':'autopay_authorization_requested',{id:obj.id,payer:obj.payerName,amount:obj.amount,frequency:obj.frequency});save();return obj};
 $('#autoPayForm').onsubmit=e=>{e.preventDefault();const obj=saveAutoPayRecord();if(!obj)return;closeModal();render('payments');toast('AutoPay authorization request saved. Gateway authorization is still required.')};
 $('#authorizeRazorpay').onclick=async()=>{const obj=saveAutoPayRecord();if(!obj)return;try{const r=await fetch('/api/autopay/create',{method:'POST',headers:{'Content-Type':'application/json','X-Admin-Email':currentUser.email},body:JSON.stringify({payerName:obj.payerName,payerEmail:obj.email,payerType:obj.payerType,amount:obj.amount,frequency:obj.frequency,consent:true})});const data=await r.json();if(!r.ok)throw new Error(data.error||'Gateway request failed');obj.mandateId=data.id;obj.gatewaySubscriptionId=data.id;obj.status='Pending Authorization';save();auditPayment('razorpay_authorization_created',{id:obj.id,gatewaySubscriptionId:data.id});if(data.short_url){window.open(data.short_url,'_blank','noopener');toast('Razorpay authorization page opened. Complete payer consent there.')}else toast('Razorpay authorization request created.');closeModal();render('payments')}catch(err){toast('Razorpay backend unavailable: '+err.message)}};
}
function openRetryPolicyModal(){ensurePaymentState();const c=db.paymentConfig;openModal(`<h3>AutoPay Retry Policy</h3><form id="retryForm" class="form-grid"><div class="field"><label>Max retries</label><input id="retryCount" type="number" min="0" max="5" value="${c.retryCount}"></div><div class="field"><label>Retry delay (hours)</label><input id="retryDelay" type="number" min="1" max="168" value="${c.retryDelayHours}"></div><div class="field span2"><label class="consent-check"><input id="reminders" type="checkbox" ${c.reminders?'checked':''}> Send pre-debit and failure reminders from the backend notification service</label></div><div class="modal-actions span2"><button type="button" class="ghost" onclick="closeModal()">Cancel</button><button class="primary">Save Policy</button></div></form>`);$('#retryForm').onsubmit=e=>{e.preventDefault();db.paymentConfig.retryCount=Math.min(5,Math.max(0,Number($('#retryCount').value)||0));db.paymentConfig.retryDelayHours=Math.min(168,Math.max(1,Number($('#retryDelay').value)||24));db.paymentConfig.reminders=$('#reminders').checked;save();auditPayment('retry_policy_updated',db.paymentConfig);closeModal();render('payments')}}

async function updateAutoPay(id,status){ensurePaymentState();const a=db.autoPays.find(x=>x.id===id);if(!a)return;const old=a.status;if(a.gatewaySubscriptionId||a.mandateId){const endpoint=status==='Paused'?'pause':status==='Active'?'resume':'cancel';try{const r=await fetch('/api/autopay/'+encodeURIComponent(a.gatewaySubscriptionId||a.mandateId)+'/'+endpoint,{method:'POST',headers:{'X-Admin-Email':currentUser.email}});const data=await r.json();if(!r.ok)throw new Error(data.error||'Gateway update failed');}catch(err){toast('Gateway update failed: '+err.message);return}}a.status=status;if(status==='Active'&&!a.nextDate)a.nextDate=new Date().toISOString().slice(0,10);save();auditPayment('autopay_status_changed',{id,payer:a.payerName,from:old,to:status});render('payments');toast(`AutoPay ${status.toLowerCase()}`)}
window.pauseAutoPay=id=>updateAutoPay(id,'Paused');window.resumeAutoPay=id=>updateAutoPay(id,'Active');window.cancelAutoPay=id=>{if(confirm('Cancel this AutoPay mandate? The gateway mandate will be cancelled when backend is configured.'))updateAutoPay(id,'Cancelled')};

window.viewPartner=id=>{const p=(db.partners||[]).find(x=>x.id===id);if(!p)return;
 const labels={decisionNote:'Decision Note',decidedBy:'Decided By',decidedAt:'Decided At',updatedBy:'Last Updated By',updatedAt:'Last Updated',fullName:'Full Name',dob:'Date of Birth',gmail:'Email',contactNumber:'Contact Number',whatsappNumber:'WhatsApp Number',cityOrVillage:'Village / City',location:'Location / Area',fullAddress:'Full Address',address:'Full Address',experience:'Experience',companyName:'Company Name',businessName:'Business Name',businessType:'Business Type',gstNumber:'GST Number',panNumber:'PAN Number',vehicleDetails:'Vehicle Details',serviceType:'Service Type',submittedAt:'Submitted At',appId:'Application ID',type:'Application Type',status:'Status',pincode:'PIN Code',district:'District',state:'State'};
 const skip=new Set(['decisionNote','decidedBy','decidedAt','id','portalType','serverSynced','name','contact','mobile','whatsapp','email','city','street','locality','nearby','landmark','education','remarks']);
 const pretty=k=>labels[k]||k.replace(/([A-Z])/g,' $1').replace(/^./,c=>c.toUpperCase());
 const order=['appId','type','status','submittedAt'];
 if(p.fullAddress&&p.fullAddress===p.address)skip.add('address');
 const keys=[...order.filter(k=>p[k]),...Object.keys(p).filter(k=>!order.includes(k)&&!skip.has(k)&&p[k]!==''&&p[k]!=null)];
 const rows=keys.map(k=>`<div class="field"><label>${esc(pretty(k))}</label><div>${esc(['submittedAt','updatedAt','decidedAt'].includes(k)?fmtDate(p[k]):String(p[k]))}</div></div>`).join('');
 const pid=esc(p.id);
 const decided=!isPendingPartner(p);
 const decisionBox=decided?`<div class="decision-box ${p.status==='Accepted'?'accepted':'rejected'}"><b>${p.status==='Accepted'?'✓ Accepted':'✕ Rejected'}</b>${p.decidedBy?` by ${esc(p.decidedBy)}`:''}${p.decidedAt?` on ${esc(fmtDate(p.decidedAt))}`:''}${p.decisionNote?`<div>${esc(p.decisionNote)}</div>`:''}</div>`:`<div class="decision-box pending"><b>Waiting for decision</b> - current status: ${esc(p.status||'New')}</div>`;
 const actions=decided?`<button type="button" class="ghost" onclick="decidePartner('${pid}','Pending')">↺ Undo decision</button>`:`<button type="button" class="primary accept-fill" onclick="decidePartner('${pid}','Accepted')">✓ Accept</button><button type="button" class="primary danger-fill" onclick="decidePartner('${pid}','Rejected')">✕ Reject</button>`;
 openModal(`<h3>${esc(p.type)} Application Form - ${esc(p.name||'')}</h3>${decisionBox}<div class="form-grid">${rows}</div><div class="modal-actions"><button type="button" class="ghost" onclick="closeModal()">Close</button>${actions}</div>`)};
